effects.css:
@keyframes sl-glitch-base {
  0%, 4%, 12%, 45%, 52%, 78%, 84%, 100% { transform: translate(0,0); }
  5%   { transform: translate(calc(var(--sl-ts-int) * 3px), 0); }
  8%   { transform: translate(calc(var(--sl-ts-int) * -4px), 0); }
  46%  { transform: translate(calc(var(--sl-ts-int) * -3px), 0); }
  49%  { transform: translate(calc(var(--sl-ts-int) * 4px), 0); }
  79%  { transform: translate(calc(var(--sl-ts-int) * 5px), 0); }
  82%  { transform: translate(calc(var(--sl-ts-int) * -4px), 0); }
}

@keyframes sl-glitch-a {
  0%, 100% { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  5%       { transform: translate(calc(var(--sl-ts-int) * -8px), 0); clip-path: inset(18% 0 58% 0); opacity: 1; }
  9%       { transform: translate(calc(var(--sl-ts-int) * 5px), 0);  clip-path: inset(58% 0 15% 0); opacity: 1; }
  12%      { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  46%      { transform: translate(calc(var(--sl-ts-int) * 6px), 0);  clip-path: inset(35% 0 40% 0); opacity: 1; }
  50%      { transform: translate(calc(var(--sl-ts-int) * -5px), 0); clip-path: inset(8% 0 75% 0); opacity: 1; }
  53%      { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  79%      { transform: translate(calc(var(--sl-ts-int) * -7px), 0); clip-path: inset(72% 0 5% 0); opacity: 1; }
  83%      { transform: translate(calc(var(--sl-ts-int) * 8px), 0);  clip-path: inset(5% 0 80% 0); opacity: 1; }
}

@keyframes sl-glitch-b {
  0%, 100% { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  7%       { transform: translate(calc(var(--sl-ts-int) * 7px), 0);  clip-path: inset(50% 0 30% 0); opacity: 1; }
  10%      { transform: translate(calc(var(--sl-ts-int) * -6px), 0); clip-path: inset(12% 0 70% 0); opacity: 1; }
  14%      { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  32%      { transform: translate(calc(var(--sl-ts-int) * -8px), 0); clip-path: inset(25% 0 55% 0); opacity: 1; }
  36%      { transform: translate(calc(var(--sl-ts-int) * 5px), 0);  clip-path: inset(65% 0 20% 0); opacity: 1; }
  39%      { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  70%      { transform: translate(calc(var(--sl-ts-int) * 4px), 0);  clip-path: inset(80% 0 10% 0); opacity: 1; }
  74%      { transform: translate(calc(var(--sl-ts-int) * -7px), 0); clip-path: inset(0 0 90% 0); opacity: 1; }
}

[data-text-style="glitch"] .succy-label-text {
    position: relative;
    isolation: isolate;
    animation: sl-glitch-base calc(var(--sl-ts-dur) * 1.4) steps(1, end) infinite;
    text-shadow:
        calc(var(--sl-ts-int) * 1.5px) 0 rgba(255, 0, 80, 0.30),
        calc(var(--sl-ts-int) * -1.5px) 0 rgba(0, 220, 255, 0.30);
}
[data-text-style="glitch"] .succy-label-text::before,
[data-text-style="glitch"] .succy-label-text::after {
    content: attr(data-text);
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
    pointer-events: none;
    will-change: transform, clip-path, opacity;
}
[data-text-style="glitch"] .succy-label-text::before {
    color: var(--sl-ts-col);
    animation: sl-glitch-a calc(var(--sl-ts-dur) * 1.4) steps(1, end) infinite;
}
[data-text-style="glitch"] .succy-label-text::after {
    color: var(--sl-ts-col-b);
    animation: sl-glitch-b calc(var(--sl-ts-dur) * 1.4) steps(1, end) infinite;
        animation-delay: calc(var(--sl-ts-dur) * -0.15);}

@keyframes sl-cf-base {
  0%, 8%, 20%, 30%, 42%, 58%, 70%, 88%, 100% { transform: translate(0,0); }
  10%  { transform: translate(calc(var(--sl-ts-int) * 6px), calc(var(--sl-ts-int) * -1px)); }
  16%  { transform: translate(calc(var(--sl-ts-int) * -8px), 0); }
  34%  { transform: translate(calc(var(--sl-ts-int) * 5px), calc(var(--sl-ts-int) * 1px)); }
  44%  { transform: translate(calc(var(--sl-ts-int) * -6px), 0); }
  60%  { transform: translate(calc(var(--sl-ts-int) * 7px), 0); }
  74%  { transform: translate(calc(var(--sl-ts-int) * -5px), calc(var(--sl-ts-int) * 1px)); }
  90%  { transform: translate(calc(var(--sl-ts-int) * 4px), 0); }
}

@keyframes sl-cf-slice-a {
  0%, 100% { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  8%       { transform: translate(calc(var(--sl-ts-int) * -14px), 0); clip-path: inset(22% 0 48% 0); opacity: 1; }
  11%      { transform: translate(calc(var(--sl-ts-int) * 12px), 0);  clip-path: inset(72% 0 8% 0); opacity: 1; }
  14%      { transform: translate(calc(var(--sl-ts-int) * -10px), 0); clip-path: inset(5% 0 78% 0); opacity: 1; }
  20%      { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  32%      { transform: translate(calc(var(--sl-ts-int) * 15px), 0);  clip-path: inset(45% 0 30% 0); opacity: 1; }
  36%      { transform: translate(calc(var(--sl-ts-int) * -18px), 0); clip-path: inset(15% 0 55% 0); opacity: 1; }
  42%      { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  58%      { transform: translate(calc(var(--sl-ts-int) * -12px), 0); clip-path: inset(60% 0 20% 0); opacity: 1; }
  62%      { transform: translate(calc(var(--sl-ts-int) * 14px), 0);  clip-path: inset(10% 0 75% 0); opacity: 1; }
  70%      { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  88%      { transform: translate(calc(var(--sl-ts-int) * -16px), 0); clip-path: inset(38% 0 42% 0); opacity: 1; }
  92%      { transform: translate(calc(var(--sl-ts-int) * 11px), 0);  clip-path: inset(80% 0 5% 0); opacity: 1; }
}

@keyframes sl-cf-slice-b {
  0%, 100% { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  6%       { transform: translate(calc(var(--sl-ts-int) * 13px), 0);  clip-path: inset(65% 0 18% 0); opacity: 1; }
  9%       { transform: translate(calc(var(--sl-ts-int) * -11px), 0); clip-path: inset(25% 0 62% 0); opacity: 1; }
  12%      { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  28%      { transform: translate(calc(var(--sl-ts-int) * -17px), 0); clip-path: inset(50% 0 28% 0); opacity: 1; }
  30%      { transform: translate(calc(var(--sl-ts-int) * 12px), 0);  clip-path: inset(2% 0 88% 0); opacity: 1; }
  34%      { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  60%      { transform: translate(calc(var(--sl-ts-int) * 16px), 0);  clip-path: inset(40% 0 42% 0); opacity: 1; }
  64%      { transform: translate(calc(var(--sl-ts-int) * -14px), 0); clip-path: inset(85% 0 2% 0); opacity: 1; }
  68%      { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  84%      { transform: translate(calc(var(--sl-ts-int) * -15px), 0); clip-path: inset(12% 0 70% 0); opacity: 1; }
  87%      { transform: translate(calc(var(--sl-ts-int) * 18px), 0);  clip-path: inset(58% 0 22% 0); opacity: 1; }
}

[data-text-style="cyber_fault"] .succy-label-text {
    position: relative;
    isolation: isolate;
    animation: sl-cf-base calc(var(--sl-ts-dur) * 1.8) steps(1, end) infinite;
    text-shadow:
        calc(var(--sl-ts-int) * 2px) 0 rgba(255, 0, 60, 0.35),
        calc(var(--sl-ts-int) * -2px) 0 rgba(0, 240, 255, 0.35);
}
[data-text-style="cyber_fault"] .succy-label-text::before,
[data-text-style="cyber_fault"] .succy-label-text::after {
    content: attr(data-text);
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
    pointer-events: none;
    will-change: transform, clip-path, opacity;
    font-weight: inherit;
}
[data-text-style="cyber_fault"] .succy-label-text::before {
    color: var(--sl-ts-col);
    animation: sl-cf-slice-a calc(var(--sl-ts-dur) * 1.8) steps(1, end) infinite;
}
[data-text-style="cyber_fault"] .succy-label-text::after {
    color: var(--sl-ts-col-b);
    animation: sl-cf-slice-b calc(var(--sl-ts-dur) * 1.8) steps(1, end) infinite;
    animation-delay: calc(var(--sl-ts-dur) * -0.35);
}

@keyframes sl-vhs-tracking {
  0%, 100% { transform: translate(0,0); filter: none; }
  6%       { transform: translate(calc(var(--sl-ts-int) * -3px), 0); filter: hue-rotate(12deg) saturate(1.4); }
  9%       { transform: translate(0,0); filter: none; }
  28%      { transform: translate(calc(var(--sl-ts-int) * 4px), 0);  filter: hue-rotate(-8deg); }
  31%      { transform: translate(0,0); filter: none; }
  55%      { transform: translate(calc(var(--sl-ts-int) * -5px), 0); filter: hue-rotate(15deg) saturate(1.5); }
  58%      { transform: translate(0,0); filter: none; }
  82%      { transform: translate(calc(var(--sl-ts-int) * 3px), 0);  filter: hue-rotate(-10deg); }
  85%      { transform: translate(0,0); filter: none; }
}

@keyframes sl-vhs-band {
  0%   { transform: translateY(-120%); opacity: 0; }
  8%   { opacity: 1; }
  60%  { opacity: 1; }
  68%  { transform: translateY(120%);  opacity: 0; }
  100% { transform: translateY(120%);  opacity: 0; }
}

[data-text-style="vhs"] .succy-label-text {
    position: relative;
    isolation: isolate;
    animation: sl-vhs-tracking calc(var(--sl-ts-dur) * 2.2) steps(1, end) infinite;
    text-shadow:
        calc(var(--sl-ts-int) * 2px) 0 rgba(255,   0,  80, 0.55),
        calc(var(--sl-ts-int) * -2px) 0 rgba(  0, 220, 255, 0.55);
}
[data-text-style="vhs"] .succy-label-text::before {
    content: attr(data-text);
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
    pointer-events: none;
    color: var(--sl-ts-col);
    mix-blend-mode: screen;
    clip-path: polygon(0 0, 100% 0, 100% 8%, 0 8%);
    animation: sl-vhs-band calc(var(--sl-ts-dur) * 2.2) linear infinite;
    will-change: transform, opacity;
}
[data-text-style="vhs"] .succy-label-text::after {
    content: attr(data-text);
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
    pointer-events: none;
    color: var(--sl-ts-col-b);
    mix-blend-mode: screen;
    clip-path: polygon(0 92%, 100% 92%, 100% 100%, 0 100%);
    animation: sl-vhs-band calc(var(--sl-ts-dur) * 2.2) linear infinite;
    animation-delay: calc(var(--sl-ts-dur) * -1.1);
    will-change: transform, opacity;
}

@keyframes sl-chr-drift {
  0%, 100% { text-shadow:
    calc(var(--sl-ts-int) *  3px) 0 0 var(--sl-ts-col),
    calc(var(--sl-ts-int) * -3px) 0 0 var(--sl-ts-col-b);
  }
  25% { text-shadow:
    calc(var(--sl-ts-int) *  4px) calc(var(--sl-ts-int) * 1px) 0 var(--sl-ts-col),
    calc(var(--sl-ts-int) * -4px) calc(var(--sl-ts-int) * -1px) 0 var(--sl-ts-col-b);
  }
  50% { text-shadow:
    calc(var(--sl-ts-int) *  2px) calc(var(--sl-ts-int) * 2px) 0 var(--sl-ts-col),
    calc(var(--sl-ts-int) * -2px) calc(var(--sl-ts-int) * -2px) 0 var(--sl-ts-col-b);
  }
  75% { text-shadow:
    calc(var(--sl-ts-int) *  4px) calc(var(--sl-ts-int) * -1px) 0 var(--sl-ts-col),
    calc(var(--sl-ts-int) * -4px) calc(var(--sl-ts-int) * 1px) 0 var(--sl-ts-col-b);
  }
}

[data-text-style="chromatic"] .succy-label-text {
    color: var(--sl-font-col);
    animation: sl-chr-drift var(--sl-ts-dur) ease-in-out infinite;
    will-change: text-shadow;
}

@keyframes sl-dm-base {
  0%, 100% { transform: translate(0,0); }
  12% { transform: translate(calc(var(--sl-ts-int) * -1px), 0); }
  18% { transform: translate(calc(var(--sl-ts-int) *  2px), 0); }
  24% { transform: translate(0,0); }
  52% { transform: translate(calc(var(--sl-ts-int) *  1px), 0); }
  60% { transform: translate(calc(var(--sl-ts-int) * -2px), 0); }
  66% { transform: translate(0,0); }
}

@keyframes sl-dm-block-a {
  0%, 100% { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  12%      { transform: translate(calc(var(--sl-ts-int) * -10px), 0); clip-path: inset(35% 0 55% 0); opacity: 1; }
  16%      { transform: translate(calc(var(--sl-ts-int) *   9px), 0); clip-path: inset(68% 0 22% 0); opacity: 1; }
  22%      { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  52%      { transform: translate(calc(var(--sl-ts-int) *  11px), 0); clip-path: inset(8% 0 82% 0); opacity: 1; }
  56%      { transform: translate(calc(var(--sl-ts-int) * -12px), 0); clip-path: inset(72% 0 14% 0); opacity: 1; }
  62%      { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
}

@keyframes sl-dm-block-b {
  0%, 100% { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  6%       { transform: translate(calc(var(--sl-ts-int) *   8px), 0); clip-path: inset(48% 0 42% 0); opacity: 1; }
  10%      { transform: translate(calc(var(--sl-ts-int) * -10px), 0); clip-path: inset(20% 0 68% 0); opacity: 1; }
  14%      { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  40%      { transform: translate(calc(var(--sl-ts-int) * -13px), 0); clip-path: inset(60% 0 26% 0); opacity: 1; }
  44%      { transform: translate(calc(var(--sl-ts-int) *  10px), 0); clip-path: inset(15% 0 78% 0); opacity: 1; }
  48%      { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  76%      { transform: translate(calc(var(--sl-ts-int) *   7px), 0); clip-path: inset(40% 0 48% 0); opacity: 1; }
  80%      { transform: translate(calc(var(--sl-ts-int) *  -9px), 0); clip-path: inset(78% 0 10% 0); opacity: 1; }
  86%      { transform: translate(0,0); clip-path: inset(0 0 0 0); opacity: 0; }
}

[data-text-style="datamosh"] .succy-label-text {
    position: relative;
    isolation: isolate;
    animation: sl-dm-base calc(var(--sl-ts-dur) * 1.6) steps(1, end) infinite;
    text-shadow:
        calc(var(--sl-ts-int) * 1.5px) 0 rgba(255, 0, 80, 0.25),
        calc(var(--sl-ts-int) * -1.5px) 0 rgba(0, 220, 255, 0.25);
}
[data-text-style="datamosh"] .succy-label-text::before,
[data-text-style="datamosh"] .succy-label-text::after {
    content: attr(data-text);
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
    pointer-events: none;
    will-change: transform, clip-path, opacity;
    font-weight: inherit;
}
[data-text-style="datamosh"] .succy-label-text::before {
    color: var(--sl-ts-col);
    animation: sl-dm-block-a calc(var(--sl-ts-dur) * 1.6) steps(1, end) infinite;
}
[data-text-style="datamosh"] .succy-label-text::after {
    color: var(--sl-ts-col-b);
    animation: sl-dm-block-b calc(var(--sl-ts-dur) * 1.6) steps(1, end) infinite;
        animation-delay: calc(var(--sl-ts-dur) * -0.55);}

@keyframes sl-ol-pulse {
  0%, 100% { -webkit-text-stroke-width: calc(0.5px + 2.5px * var(--sl-ts-int)); }
  50%      { -webkit-text-stroke-width: calc(0.5px + 4.5px * var(--sl-ts-int)); }
}
[data-text-style="outline"] .succy-label-text {
    color: transparent;
    -webkit-text-stroke: calc(0.5px + 3px * var(--sl-ts-int)) var(--sl-ts-col);
    paint-order: stroke fill;
    animation: sl-ol-pulse var(--sl-ts-dur) ease-in-out infinite;
}

@keyframes sl-old-pulse {
  0%, 100% { filter: drop-shadow(0 0 calc(2px + 6px * var(--sl-ts-int)) var(--sl-ts-col-b)); }
  50%      { filter: drop-shadow(0 0 calc(6px + 18px * var(--sl-ts-int)) var(--sl-ts-col-b)); }
}
[data-text-style="outline_double"] .succy-label-text {
    color: var(--sl-font-col);
    -webkit-text-stroke: calc(0.5px + 2px * var(--sl-ts-int)) var(--sl-ts-col);
    paint-order: stroke fill;
    animation: sl-old-pulse var(--sl-ts-dur) ease-in-out infinite;
}

@keyframes sl-glw-pulse {
  0%, 100% { text-shadow:
    0 0 calc(4px + 15px * var(--sl-ts-int)) var(--sl-ts-col),
    0 0 calc(8px + 30px * var(--sl-ts-int)) var(--sl-ts-col); }
  50%      { text-shadow:
    0 0 calc(6px + 25px * var(--sl-ts-int)) var(--sl-ts-col),
    0 0 calc(12px + 50px * var(--sl-ts-int)) var(--sl-ts-col); }
}
[data-text-style="glow"] .succy-label-text {
    animation: sl-glw-pulse var(--sl-ts-dur) ease-in-out infinite;
}

@keyframes sl-nn-pulse {
  0%, 100% { text-shadow:
    0 0 calc(4px + 10px * var(--sl-ts-int)) var(--sl-ts-col),
    0 0 calc(8px + 20px * var(--sl-ts-int)) var(--sl-ts-col-b); }
  50%      { text-shadow:
    0 0 calc(8px + 20px * var(--sl-ts-int)) var(--sl-ts-col),
    0 0 calc(16px + 40px * var(--sl-ts-int)) var(--sl-ts-col-b); }
}
[data-text-style="neon"] .succy-label-text {
    color: var(--sl-font-col);
    animation: sl-nn-pulse var(--sl-ts-dur) ease-in-out infinite;
}

@keyframes sl-nf-anim {
  0%, 18%, 22%, 25%, 53%, 57%, 100% {
    opacity: 1;
    text-shadow: 0 0 calc(4px + 20px * var(--sl-ts-int)) var(--sl-ts-col),
                 0 0 calc(8px + 40px * var(--sl-ts-int)) var(--sl-ts-col-b);
  }
  20%, 24%, 55% { opacity: 0.4; text-shadow: none; }
}
[data-text-style="neon_flicker"] .succy-label-text {
    color: var(--sl-font-col);
    animation: sl-nf-anim var(--sl-ts-dur) infinite;
}

@keyframes sl-sh-orbit {
  0%   { text-shadow: calc( 2px +  8px * var(--sl-ts-int)) calc( 2px +  8px * var(--sl-ts-int)) calc(2px +  8px * var(--sl-ts-int)) var(--sl-ts-col); }
  25%  { text-shadow: calc(-2px -  8px * var(--sl-ts-int)) calc( 2px +  8px * var(--sl-ts-int)) calc(2px +  8px * var(--sl-ts-int)) var(--sl-ts-col); }
  50%  { text-shadow: calc(-2px -  8px * var(--sl-ts-int)) calc(-2px -  8px * var(--sl-ts-int)) calc(2px +  8px * var(--sl-ts-int)) var(--sl-ts-col); }
  75%  { text-shadow: calc( 2px +  8px * var(--sl-ts-int)) calc(-2px -  8px * var(--sl-ts-int)) calc(2px +  8px * var(--sl-ts-int)) var(--sl-ts-col); }
  100% { text-shadow: calc( 2px +  8px * var(--sl-ts-int)) calc( 2px +  8px * var(--sl-ts-int)) calc(2px +  8px * var(--sl-ts-int)) var(--sl-ts-col); }
}
[data-text-style="shadow"] .succy-label-text {
    animation: sl-sh-orbit var(--sl-ts-dur) linear infinite;
}

@keyframes sl-3d-shift {
  0%, 100% { text-shadow:
    calc(var(--sl-ts-int) * 1px) calc(var(--sl-ts-int) * 1px) 0 var(--sl-ts-col),
    calc(var(--sl-ts-int) * 2px) calc(var(--sl-ts-int) * 2px) 0 var(--sl-ts-col),
    calc(var(--sl-ts-int) * 3px) calc(var(--sl-ts-int) * 3px) 0 var(--sl-ts-col),
    calc(var(--sl-ts-int) * 4px) calc(var(--sl-ts-int) * 4px) calc(var(--sl-ts-int) * 6px) var(--sl-ts-col); }
  50%      { text-shadow:
    calc(var(--sl-ts-int) * 2px) calc(var(--sl-ts-int) * 2px) 0 var(--sl-ts-col),
    calc(var(--sl-ts-int) * 4px) calc(var(--sl-ts-int) * 4px) 0 var(--sl-ts-col),
    calc(var(--sl-ts-int) * 6px) calc(var(--sl-ts-int) * 6px) 0 var(--sl-ts-col),
    calc(var(--sl-ts-int) * 8px) calc(var(--sl-ts-int) * 8px) calc(var(--sl-ts-int) * 12px) var(--sl-ts-col); }
}
[data-text-style="3d"] .succy-label-text {
    animation: sl-3d-shift var(--sl-ts-dur) ease-in-out infinite;
}

@keyframes sl-ins-shift {
  0%, 100% { text-shadow:
    calc(-1px - 1px * var(--sl-ts-int)) calc(-1px - 1px * var(--sl-ts-int)) 1px var(--sl-ts-col),
    calc( 1px + 1px * var(--sl-ts-int)) calc( 1px + 1px * var(--sl-ts-int)) 2px var(--sl-ts-col-b); }
  50%      { text-shadow:
    calc(-2px - 2px * var(--sl-ts-int)) calc(-2px - 2px * var(--sl-ts-int)) 2px var(--sl-ts-col),
    calc( 2px + 2px * var(--sl-ts-int)) calc( 2px + 2px * var(--sl-ts-int)) 3px var(--sl-ts-col-b); }
}
[data-text-style="inset"] .succy-label-text {
    color: var(--sl-font-col);
    animation: sl-ins-shift var(--sl-ts-dur) ease-in-out infinite;
}

@keyframes sl-emb-shift {
  0%, 100% { text-shadow:
    calc(1px + 2px * var(--sl-ts-int)) calc(1px + 2px * var(--sl-ts-int)) 0 var(--sl-ts-col),
    calc(-1px - 2px * var(--sl-ts-int)) calc(-1px - 2px * var(--sl-ts-int)) 0 var(--sl-ts-col-b); }
  50%      { text-shadow:
    calc(2px + 3px * var(--sl-ts-int)) calc(2px + 3px * var(--sl-ts-int)) 0 var(--sl-ts-col),
    calc(-2px - 3px * var(--sl-ts-int)) calc(-2px - 3px * var(--sl-ts-int)) 0 var(--sl-ts-col-b); }
}
[data-text-style="emboss"] .succy-label-text {
    color: var(--sl-font-col);
        animation: sl-emb-shift var(--sl-ts-dur) ease-in-out infinite;
}

@keyframes sl-shimmer-anim {
  0%   { background-position: -200% center; }
  100% { background-position: 200% center; }
}
[data-text-style="shimmer"] .succy-label-text {
    background: linear-gradient(90deg,
        var(--sl-font-col) 0%,
        var(--sl-ts-col) 50%,
