}

@keyframes sl-float-anim {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(calc(var(--sl-ts-int) * -8px)); }
}
[data-text-style="float"] .succy-label-text {
    display: inline-block;
    animation: sl-float-anim var(--sl-ts-dur) ease-in-out infinite;
}

@keyframes sl-rise-anim {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(calc(var(--sl-ts-int) * -18px)); }
}
[data-text-style="rise"] .succy-label-text {
    display: inline-block;
    animation: sl-rise-anim var(--sl-ts-dur) ease-out infinite;
}

@keyframes sl-sink-anim {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(calc(var(--sl-ts-int) * 18px)); }
}
[data-text-style="sink"] .succy-label-text {
    display: inline-block;
    animation: sl-sink-anim var(--sl-ts-dur) ease-in infinite;
