@keyframes sl-pulse-anim {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(calc(1 + var(--sl-ts-int) * 0.12)); }
}
[data-text-style="pulse"] .succy-label-text {
    display: inline-block;
    transform-origin: center;
    animation: sl-pulse-anim var(--sl-ts-dur) ease-in-out infinite;
}

@keyframes sl-bounce-anim {
  0%, 20%, 50%, 80%, 100% { transform: translateY(0); }
  40% { transform: translateY(calc(var(--sl-ts-int) * -18px)); }
  60% { transform: translateY(calc(var(--sl-ts-int) * -8px)); }
}
[data-text-style="bounce"] .succy-label-text {
    display: inline-block;
    animation: sl-bounce-anim var(--sl-ts-dur) cubic-bezier(0.28, 0.84, 0.42, 1) infinite;
}

@keyframes sl-rot-anim {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}
[data-text-style="rotate_slow"] .succy-label-text {
    display: inline-block;
    transform-origin: center;
    animation: sl-rot-anim var(--sl-ts-dur) linear infinite;
}

@keyframes sl-skew-anim {
  0%, 100% { transform: skewX(calc(var(--sl-ts-int) * -15deg)); }
  50%      { transform: skewX(calc(var(--sl-ts-int) * 15deg)); }
}
[data-text-style="skew_anim"] .succy-label-text {
    display: inline-block;
    transform-origin: center;
    animation: sl-skew-anim var(--sl-ts-dur) ease-in-out infinite;
}

@keyframes sl-shiver-anim {
  0%, 100% { transform: translate(0, 0); }
  25%      { transform: translate(calc(var(--sl-ts-int) * -2px), calc(var(--sl-ts-int) * 2px)); }
  50%      { transform: translate(calc(var(--sl-ts-int) * 2px), calc(var(--sl-ts-int) * -2px)); }
  75%      { transform: translate(calc(var(--sl-ts-int) * -2px), calc(var(--sl-ts-int) * -2px)); }
}
[data-text-style="shiver"] .succy-label-text {
    display: inline-block;
    animation: sl-shiver-anim calc(var(--sl-ts-dur) * 0.4) linear infinite;
}

@keyframes sl-ghost-anim {
  0%, 100% { filter: blur(0px); opacity: 1; transform: translateY(0) scale(1); }
  50%      { filter: blur(calc(var(--sl-ts-int) * 4px)); opacity: 0.5; transform: translateY(calc(var(--sl-ts-int) * -5px)) scale(1.02); }
}
[data-text-style="ghost"] .succy-label-text {
    color: var(--sl-font-col);
    text-shadow: 0 0 calc(var(--sl-ts-int) * 15px) var(--sl-ts-col);
        animation: sl-ghost-anim var(--sl-ts-dur) ease-in-out infinite;
}

@keyframes sl-fb-anim {
  0%, 100% { filter: blur(0px); }
  50%      { filter: blur(calc(var(--sl-ts-int) * 5px)); }
}
[data-text-style="focus_blur"] .succy-label-text {
    animation: sl-fb-anim var(--sl-ts-dur) ease-in-out infinite;
}

@keyframes sl-scl-scroll {
  0%   { background-position: 0 0; }
  100% { background-position: 0 calc(-20px - var(--sl-ts-int) * 30px); }
}
[data-text-style="scanline"] .succy-label-text {
    background: repeating-linear-gradient(
        to bottom,
        transparent 0 calc(2px + var(--sl-ts-int) * 3px),
        var(--sl-ts-col) calc(2px + var(--sl-ts-int) * 3px) calc(4px + var(--sl-ts-int) * 5px)
    );
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
    animation: sl-scl-scroll var(--sl-ts-dur) linear infinite;
}

@keyframes sl-holo-flicker {
  0%, 100% { opacity: calc(0.35 + 0.45 * var(--sl-ts-int)); }
  4%       { opacity: calc(0.05 + 0.15 * var(--sl-ts-int)); }
  8%       { opacity: calc(0.35 + 0.45 * var(--sl-ts-int)); }
  12%      { opacity: calc(0.55 + 0.40 * var(--sl-ts-int)); }
  50%      { opacity: calc(0.30 + 0.50 * var(--sl-ts-int)); }
  52%      { opacity: calc(0.05 + 0.10 * var(--sl-ts-int)); }
  54%      { opacity: calc(0.30 + 0.50 * var(--sl-ts-int)); }
}
[data-text-style="hologram"] .succy-label-text {
    mix-blend-mode: screen;
    color: var(--sl-font-col);
    text-shadow:
        0 0 calc(4px + 8px * var(--sl-ts-int)) var(--sl-ts-col),
        0 0 calc(10px + 22px * var(--sl-ts-int)) var(--sl-ts-col-b);
    animation: sl-holo-flicker var(--sl-ts-dur) steps(1, end) infinite;
}

@keyframes sl-ov-pulse {
  0%, 100% { opacity: calc(0.65 + 0.35 * var(--sl-ts-int)); }
  50%      { opacity: calc(0.35 + 0.35 * var(--sl-ts-int)); }
}
[data-text-style="overlay"] .succy-label-text {
    mix-blend-mode: overlay;
    color: var(--sl-font-col);
    animation: sl-ov-pulse var(--sl-ts-dur) ease-in-out infinite;
}

@keyframes sl-fire-flicker {
  0%, 100% { filter: drop-shadow(0 0 calc(6px + 14px * var(--sl-ts-int)) var(--sl-ts-col-b)) brightness(1); }
  33%      { filter: drop-shadow(0 0 calc(10px + 22px * var(--sl-ts-int)) var(--sl-ts-col-b)) brightness(1.15); }
  66%      { filter: drop-shadow(0 0 calc(7px + 16px * var(--sl-ts-int)) var(--sl-ts-col-b)) brightness(0.95); }
}
[data-text-style="fire"] .succy-label-text {
    background: linear-gradient(to top,
        var(--sl-font-col) 0%,
        var(--sl-font-col) 20%,
        var(--sl-ts-col) 55%,
        var(--sl-ts-col-b) 85%,
        transparent 100%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
    animation: sl-fire-flicker calc(var(--sl-ts-dur) * 0.28) ease-in-out infinite;
}

@keyframes sl-flame-flicker {
  0%, 100% { filter: drop-shadow(0 0 calc(8px + 18px * var(--sl-ts-int)) var(--sl-ts-col-b)) brightness(1); }
  25%      { filter: drop-shadow(0 0 calc(12px + 26px * var(--sl-ts-int)) var(--sl-ts-col-b)) brightness(1.20); }
  50%      { filter: drop-shadow(0 0 calc(6px + 14px * var(--sl-ts-int)) var(--sl-ts-col-b)) brightness(0.95); }
  75%      { filter: drop-shadow(0 0 calc(14px + 28px * var(--sl-ts-int)) var(--sl-ts-col-b)) brightness(1.15); }
}
@keyframes sl-flame-rise {
  0%, 100% { transform: translateY(0) scaleY(1); opacity: 0.9; filter: blur(2px); }
  50%      { transform: translateY(calc(var(--sl-ts-int) * -4px)) scaleY(1.08); opacity: 0.6; filter: blur(4px); }
}
[data-text-style="flame"] .succy-label-text {
    position: relative;
    isolation: isolate;
    background: linear-gradient(to top,
        var(--sl-font-col) 0%,
        var(--sl-font-col) 15%,
        var(--sl-ts-col) 45%,
        var(--sl-ts-col-b) 75%,
        var(--sl-ts-col-b) 90%,
        transparent 100%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
    animation: sl-flame-flicker calc(var(--sl-ts-dur) * 0.22) ease-in-out infinite;
}
[data-text-style="flame"] .succy-label-text::before {
    content: attr(data-text);
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
    pointer-events: none;
    background: linear-gradient(to top,
        var(--sl-ts-col) 0%,
        var(--sl-ts-col-b) 50%,
        transparent 90%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
    transform-origin: center bottom;
    animation: sl-flame-rise calc(var(--sl-ts-dur) * 0.22) ease-in-out infinite;
}

@keyframes sl-smoke-anim {
  0%, 100% { text-shadow:
    0 0 calc(5px + 15px * var(--sl-ts-int)) var(--sl-ts-col),
    0 0 calc(10px + 30px * var(--sl-ts-int)) var(--sl-ts-col-b),
    2px -2px calc(8px + 20px * var(--sl-ts-int)) var(--sl-ts-col-b);
    opacity: 1; }
  50%      { text-shadow:
    0 0 calc(8px + 20px * var(--sl-ts-int)) var(--sl-ts-col),
    4px -6px calc(15px + 35px * var(--sl-ts-int)) var(--sl-ts-col-b),
    -2px -4px calc(12px + 30px * var(--sl-ts-int)) var(--sl-ts-col-b);
    opacity: 0.85; }
}
[data-text-style="smoke"] .succy-label-text {
    color: var(--sl-font-col);
    animation: sl-smoke-anim var(--sl-ts-dur) ease-in-out infinite;
}

@keyframes sl-el-anim {
  0%, 100% { text-shadow:
    0 0 calc(3px + 10px * var(--sl-ts-int)) var(--sl-ts-col),
    0 0 calc(6px + 20px * var(--sl-ts-int)) var(--sl-ts-col);
    transform: translate(0, 0); }
  14% { text-shadow:
    -4px 0 calc(5px + 15px * var(--sl-ts-int)) var(--sl-ts-col-b),
     4px 0 calc(7px + 24px * var(--sl-ts-int)) var(--sl-ts-col);
    transform: translate(-1px, 0); }
  22% { text-shadow:
     4px 0 calc(5px + 15px * var(--sl-ts-int)) var(--sl-ts-col-b),
    -4px 0 calc(7px + 24px * var(--sl-ts-int)) var(--sl-ts-col);
    transform: translate(1px, 0); }
  38% { text-shadow:
    0 -4px calc(5px + 15px * var(--sl-ts-int)) var(--sl-ts-col-b),
    0  4px calc(7px + 24px * var(--sl-ts-int)) var(--sl-ts-col);
    transform: translate(0, -1px); }
  54% { text-shadow:
    0  4px calc(5px + 15px * var(--sl-ts-int)) var(--sl-ts-col-b),
    0 -4px calc(7px + 24px * var(--sl-ts-int)) var(--sl-ts-col);
    transform: translate(0, 1px); }
  70% { text-shadow:
    -3px -3px calc(5px + 15px * var(--sl-ts-int)) var(--sl-ts-col-b),
     3px  3px calc(7px + 24px * var(--sl-ts-int)) var(--sl-ts-col);
    transform: translate(-1px, -1px); }
}
@keyframes sl-el-pulse {
  0%, 100% { opacity: 0.7; }
  50%      { opacity: 1; }
}
[data-text-style="electric"] .succy-label-text {
    position: relative;
    isolation: isolate;
    color: var(--sl-font-col);
    animation: sl-el-anim calc(var(--sl-ts-dur) * 0.35) steps(1, end) infinite;
}
[data-text-style="electric"] .succy-label-text::before {
    content: attr(data-text);
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
    pointer-events: none;
    color: transparent;
    text-shadow:
        0 0 calc(12px + 24px * var(--sl-ts-int)) var(--sl-ts-col),
        0 0 calc(24px + 48px * var(--sl-ts-int)) var(--sl-ts-col-b);
    mix-blend-mode: screen;
    animation: sl-el-pulse calc(var(--sl-ts-dur) * 0.5) ease-in-out infinite;
}

@keyframes sl-tw-type {
  from { width: 0; }
  to   { width: 100%; }
}
@keyframes sl-tw-glow {
  0%, 49%   { text-shadow: 0 0 calc(6px + 18px * var(--sl-ts-int)) var(--sl-ts-col-b); }
  50%, 100% { text-shadow: 0 0 2px var(--sl-ts-col-b); }
}
[data-text-style="typewriter"] .succy-label-text {
    display: inline-block;
    overflow: hidden;
    white-space: nowrap;
    color: var(--sl-font-col);
    border-right: 2px solid var(--sl-ts-col);
    animation:
      sl-tw-type var(--sl-ts-dur) steps(40) infinite alternate,
      sl-tw-glow calc(var(--sl-ts-dur) * 0.15) step-end infinite;
}
